import com.google.gson.JsonParser;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch42Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm10_en_179","sm11_en_201","sm12_en_185","sm8_en_178","sm8_en_180","sm8_en_191","sm9_en_158","xy8_en_141");
    static final List<String> PRISMS=List.of("sm8_en_178","sm8_en_180","sm8_en_191","sm9_en_158");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static CardInstance card(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static void settle(ServerMatch m){NonPokemonBatch2Test.settle(m);}
    static void activate(ServerMatch m,UUID p){m.activateStadium(p,m.clientView(p).stadium().instanceId(),m.stadiumEntrySequence());}
    static void select(ServerMatch m,UUID p,UUID id){var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(id));}
    static void pick(ServerMatch m,UUID p,UUID id){var q=m.effectPokemonPrompt(p);m.chooseEffectPokemon(p,q.resolutionId(),q.step(),id);}
    static void attach(ServerMatch m,UUID p,String id){m.attachEnergyByEffect(A,p,EffectSourceZone.HAND,card(m,p,id).instanceId(),p,active(m,p));}
    static void take(ServerMatch m,UUID p){UUID victim=p.equals(A)?B:A;m.knockOutPokemonByEffect(p,victim,bench(m,victim));check(UnrestrictedAttackPrizeTest.take(m,p)==1,"Prize fixture");}
    static AttackDefinition cost(String energy){return BundledCombatData.attack(JsonParser.parseString("{\"id\":\"hit\",\"nameZh\":\"Test\",\"energyCost\":{"+energy+"},\"baseDamage\":100,\"damageType\":\"COLORLESS\",\"effectSupport\":\"SUPPORTED\"}").getAsJsonObject(),EffectRegistry.standard());}
    static ServerMatch game(String id,EnergyType energy,EnergyType type,AttackDefinition attack){return GeneratedRuleBatch8Test.fixture(List.of(),energy,type,profile(id),attack);}
    static ServerMatch aiGame(String id){var m=game(id,id.equals("sm8_en_178")?EnergyType.FIRE:EnergyType.FIGHTING,EnergyType.GRASS,GeneratedRuleBatch8Test.hit(100,false));if(id.equals("sm8_en_180"))m.placeDamageCountersByEffect(A,A,active(m,A),7);return m;}
    public static void main(String[] args){boots();beastite();dojo();costs();factory();forest();protection();System.out.println("NonPokemonBatch42Test passed: live retreat HP/confusion, own prizes, both-player prize comparison, typed attack costs, Stadium per-player costs/cure and hand-Trainer protection");}
    static void boots(){var retreat=DynamicPassiveModifierTest.trainer("STADIUM","{\"type\":\"retreat_cost_modifier\",\"target\":\"ALL_OWN_POKEMON\",\"amount\":-1}");var m=DynamicPassiveModifierTest.fixture(profile("xy8_en_141"),retreat);m.applySpecialConditionByEffect(A,A,SpecialCondition.CONFUSED);m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);m.playTrainer(A,card(m,A,"tool").instanceId(),active(m,A));check(m.activePokemonView(A).hitPoints()==320&&!m.activePokemonView(A).conditions().contains(SpecialCondition.CONFUSED)&&m.activePokemonView(A).conditions().contains(SpecialCondition.POISONED),"Heavy Boots HP, immediate cure or unrelated status");m.applySpecialConditionByEffect(A,A,SpecialCondition.CONFUSED);check(!m.activePokemonView(A).conditions().contains(SpecialCondition.CONFUSED),"Heavy Boots failed prevention");m.playTrainer(A,card(m,A,"stadium").instanceId(),null);check(m.activeRetreatCost(A)==2&&m.activePokemonView(A).hitPoints()==300,"Heavy Boots used printed retreat or cached HP");m.applySpecialConditionByEffect(A,A,SpecialCondition.CONFUSED);check(m.activePokemonView(A).conditions().contains(SpecialCondition.CONFUSED),"Boots remained active below retreat threshold");m.discardStadiumByEffect(A);check(m.activePokemonView(A).hitPoints()==320&&!m.activePokemonView(A).conditions().contains(SpecialCondition.CONFUSED),"Boots did not reactivate after Stadium left");}
    static void beastite(){for(boolean beast:List.of(false,true))for(UUID winner:List.of(A,B)){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile("sm12_en_185");c.ownFamilies=beast?Set.of(PokemonFamily.ULTRA_BEAST):Set.of();var m=GeneratedRuleBatch28Test.fixture(c);m.playTrainer(A,card(m,A,"trainer").instanceId(),active(m,A));if(winner.equals(B))m.endTurn(A);take(m,winner);if(winner.equals(B))m.endTurn(B);m.attack(A,"hit");check(m.lastAttack().finalDamage()==(beast&&winner.equals(A)?110:100),"Beastite counted opponent prizes or non-Ultra Beast");}}
    static void dojo(){for(String attached:List.of("energy","special","wrong"))for(UUID leader:List.of(A,B)){
        var m=game("sm10_en_179",EnergyType.FIGHTING,EnergyType.GRASS,GeneratedRuleBatch8Test.hit(100,false));for(UUID p:List.of(A,B))attach(m,p,attached);m.playTrainer(A,card(m,A,"trainer").instanceId(),null);if(leader.equals(B))m.endTurn(A);take(m,leader);if(leader.equals(B))m.endTurn(B);m.attack(A,"hit");check(m.lastAttack().finalDamage()==100+(attached.equals("energy")?(leader.equals(B)?40:10):0),"Dojo wrong own prize comparison or Energy kind");m.attack(B,"hit");check(m.lastAttack().finalDamage()==100+(attached.equals("energy")?(leader.equals(A)?40:10):0),"Dojo opponent recipient used Stadium controller's prizes");
    }var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile("sm10_en_179");c.ownFamilies=Set.of(PokemonFamily.ULTRA_BEAST);c.energyType=EnergyType.FIGHTING;var m=GeneratedRuleBatch28Test.fixture(c);attach(m,A,"energy");m.playTrainer(A,card(m,A,"trainer").instanceId(),null);m.attack(A,"hit");check(m.lastAttack().finalDamage()==100,"Dojo applied to Ultra Beast");}
    static void costs(){for(boolean behind:List.of(false,true))for(String energy:List.of("FIGHTING","LIGHTNING","COLORLESS")){
        var attack=cost("\""+energy+"\":1");var m=game("sm11_en_201",EnergyType.FIRE,EnergyType.GRASS,attack);m.playTrainer(A,card(m,A,"trainer").instanceId(),active(m,A));if(behind){m.endTurn(A);take(m,B);m.endTurn(B);}check(m.canPayActiveAttackCost(A,attack)==(behind&&energy.equals("FIGHTING")),"Karate Belt reduced wrong type or ignored prize requirement");
    }for(EnergyType type:List.of(EnergyType.LIGHTNING,EnergyType.GRASS))for(String energy:List.of("LIGHTNING","FIGHTING","COLORLESS")){
        var attack=cost("\""+energy+"\":1");var m=game("sm8_en_191",EnergyType.FIRE,type,attack);m.playTrainer(A,card(m,A,"trainer").instanceId(),null);for(UUID p:List.of(A,B))check(m.canPayActiveAttackCost(p,attack)==(type==EnergyType.LIGHTNING&&energy.equals("LIGHTNING")),"Thunder Mountain wrong type/owner");m.discardStadiumByEffect(A);check(!m.canPayActiveAttackCost(A,attack),"Typed discount persisted after Stadium left");
    }for(EnergyType type:List.of(EnergyType.FAIRY,EnergyType.GRASS)){var attack=cost("");var m=game("sm9_en_158",EnergyType.GRASS,type,attack);m.playTrainer(A,card(m,A,"trainer").instanceId(),null);for(UUID p:List.of(A,B)){check(m.canPayActiveAttackCost(p,attack)==(type==EnergyType.FAIRY),"Labyrinth type/owner");attach(m,p,"energy");check(m.canPayActiveAttackCost(p,attack),"Labyrinth charged more than one Colorless");}}}
    static void factory(){for(boolean empty:List.of(false,true)){var m=aiGame("sm8_en_178");m.playTrainer(A,card(m,A,"trainer").instanceId(),null);if(empty)m.drawCardsByEffect(A,A,60);for(UUID p:empty?List.of(A):List.of(A,B)){if(p.equals(B))m.endTurn(A);int hand=m.privateView(p).hand().size();check(m.canActivateStadium(p),"Heat Factory unavailable with matching cost, empty="+empty);activate(m,p);var q=m.effectCardPrompt(p);check(q.candidates().stream().allMatch(c->c.definitionId().equals("energy")),"Heat Factory accepted Special or wrong basic Energy");var paid=q.candidates().getFirst();select(m,p,paid.instanceId());settle(m);check(m.privateView(p).hand().size()==hand-1+(empty?0:3)&&m.privateView(p).discard().contains(paid)&&!m.canActivateStadium(p),"Heat Factory payment, draw or usage");}}
        var m=aiGame("sm8_en_178");m.playTrainer(A,card(m,A,"trainer").instanceId(),null);m.discardHandCardsByEffect(A,A,m.privateView(A).hand().stream().filter(c->c.definitionId().equals("energy")).map(CardInstance::instanceId).toList());check(!m.canActivateStadium(A),"Heat Factory paid with Special Energy");}
    static void forest(){for(boolean damaged:List.of(false,true)){var m=aiGame("sm8_en_180");if(!damaged)m.healDamageByEffect(A,A,active(m,A),70);m.applySpecialConditionByEffect(A,A,SpecialCondition.BURNED);m.applySpecialConditionByEffect(A,A,SpecialCondition.CONFUSED);m.playTrainer(A,card(m,A,"trainer").instanceId(),null);activate(m,A);pick(m,A,active(m,A));settle(m);check(m.activePokemonView(A).damage()==(damaged?10:0)&&m.activePokemonView(A).conditions().isEmpty()&&!m.canActivateStadium(A),"Life Forest heal/cure/usage");m.endTurn(A);m.placeDamageCountersByEffect(B,B,bench(m,B),8);activate(m,B);pick(m,B,bench(m,B));settle(m);check(m.benchPokemonView(B).getFirst().damage()==20,"Life Forest failed other player's Bench heal");}
        var wrong=game("sm8_en_180",EnergyType.GRASS,EnergyType.FIRE,GeneratedRuleBatch8Test.hit(100,false));wrong.placeDamageCountersByEffect(A,A,active(wrong,A),7);wrong.playTrainer(A,card(wrong,A,"trainer").instanceId(),null);check(!wrong.canActivateStadium(A),"Life Forest accepted non-Grass");}
    static void protection(){for(String id:PRISMS)for(UUID owner:List.of(A,B))for(String removal:List.of("faba","vacuum","discard")){
        var item=removal.equals("faba")?profile("sm8_en_173"):removal.equals("vacuum")?profile("swsh11_en_162"):DeckDiscardTriggeredAbilityTest.trainer("ITEM","{\"type\":\"discard_stadium\",\"target\":\"SELF\"}");
        var m=DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),profile(id),EnergyProfile.fixed(EnergyType.GRASS,2),GeneratedRuleBatch8Test.hit(10,false),List.of(),0,item);var stadium=card(m,owner,"stadium");if(owner.equals(B))m.endTurn(A);m.playTrainer(owner,stadium.instanceId(),null);if(owner.equals(B))m.endTurn(B);m.playTrainer(A,card(m,A,"item").instanceId(),null);if(removal.equals("vacuum"))select(m,A,m.effectCardPrompt(A).candidates().getFirst().instanceId());if(!removal.equals("discard"))select(m,A,stadium.instanceId());settle(m);check(m.clientView(A).stadium().instanceId().equals(stadium.instanceId())&&!m.privateView(owner).lostZone().contains(stadium)&&!m.privateView(owner).discard().contains(stadium),"Prism protection failed "+id+" "+removal+" "+owner);m.discardStadiumByEffect(A);check(m.clientView(A).stadium()==null,"Prism protection blocked non-Trainer rule action");
    }
        var attack=BeforeDamageAttackTest.attack("","","{\"type\":\"discard_stadium\"}");
        for(String id:PRISMS)for(boolean replace:List.of(false,true)) {var m=DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),profile(id),EnergyProfile.fixed(EnergyType.GRASS,2),attack,List.of(),0,DynamicPassiveModifierTest.plainStadium());var old=card(m,A,"stadium");m.playTrainer(A,old.instanceId(),null);if(replace){m.endTurn(A);var next=card(m,B,"item");m.playTrainer(B,next.instanceId(),null);check(m.clientView(A).stadium().instanceId().equals(next.instanceId()),"Prism blocked normal Stadium replacement");}else{attach(m,A,"energy");m.attack(A,"hit");check(m.clientView(A).stadium()==null,"Prism blocked an attack effect");}check(m.privateView(A).discard().contains(old),"Stadium failed to leave play");}
    }
}
